function draw({board,width,params}) {
 const names=['猫','鸡','狗'],colors=['#327f96','#b86838','#6c7780'];
 const o=[params.cat+params.shift,params.shift,-1+params.shift];
 const m=Math.max(...o),e=o.map(v=>Math.exp(v-m)),s=e.reduce((a,b)=>a+b,0),p=e.map(v=>v/s);
 const L=90,R=width-58,W=R-L;
 board.text('head-left','分数 o',12,25,{size:14,color:'#637782'});
 board.text('head-right','概率 p',L,25,{size:14,color:'#637782'});
 [0,.5,1].forEach((v,i)=>{const x=L+v*W;board.line('grid-'+i,x,43,x,259,'#dce4e5',1);board.text('tick-'+i,String(v),x,279,{size:13,anchor:'middle',color:'#637782'});});
 names.forEach((n,j)=>{const y=69+j*72;board.text('name-'+j,n,12,y+13,{size:17,color:colors[j]});board.text('score-'+j,o[j].toFixed(1),12,y+36,{size:14,color:'#637782'});board.rect('bar-'+j,L,y,W*p[j],23,colors[j],{rx:2});board.text('prob-'+j,p[j].toFixed(3),width-12,y+17,{size:14,anchor:'end'});});
 board.text('axis','0—1，共用概率刻度',L,302,{size:13,color:'#637782'});
 board.text('ratio','鸡 / 狗 = '+(p[1]/p[2]).toFixed(3)+'  始终不变',12,332,{size:15});
 return {logits:o,probabilities:p,sum:p.reduce((a,b)=>a+b,0),chickenDogRatio:p[1]/p[2],catChickenRatio:p[0]/p[1],convention:'手选分数；稳定 softmax；无训练或校准声明'};
}

function draw({board,width,params}) {
 const names=['猫','鸡','狗'],o=[1,0,-1],target=Number(params.target),eta=params.eta;
 const soft=v=>{const m=Math.max(...v),e=v.map(x=>Math.exp(x-m)),s=e.reduce((a,b)=>a+b,0);return e.map(x=>x/s);};
 const p=soft(o),g=p.map((x,j)=>x-(j===target?1:0)),next=o.map((x,j)=>x-eta*g[j]),q=soft(next);
 const L=100,R=width-58,W=R-L;
 board.text('axis-name','预测概率',width-12,23,{size:13,anchor:'end',color:'#637782'});
 board.line('legend-before',12,18,31,18,'#7896a3',5);board.text('legend-before-t','更新前',38,23,{size:14});
 board.line('legend-after',115,18,134,18,'#ba6b3c',5);board.text('legend-after-t','更新后',141,23,{size:14});
 [0,.5,1].forEach((v,i)=>{const x=L+v*W;board.line('grid-'+i,x,42,x,283,'#dce4e5',1);board.text('tick-'+i,String(v),x,303,{size:13,anchor:'middle',color:'#637782'});});
 names.forEach((n,j)=>{const y=58+80*j;board.text('name-'+j,n+(j===target?' ✓':''),12,y+13,{size:17,color:j===target?'#ba6b3c':'#243c46'});board.text('g-'+j,'g='+ (g[j]>0?'+':'')+g[j].toFixed(2),12,y+37,{size:13,color:'#637782'});board.rect('before-'+j,L,y,W*p[j],15,'#7896a3',{rx:2});board.rect('after-'+j,L,y+23,W*q[j],15,'#ba6b3c',{rx:2});board.text('p-'+j,p[j].toFixed(3),width-12,y+12,{size:13,anchor:'end',color:'#637782'});board.text('logit-step-'+j,'o: '+o[j].toFixed(2)+' → '+next[j].toFixed(2),L,y+60,{size:13,color:'#637782'});board.text('q-'+j,q[j].toFixed(3),width-12,y+35,{size:13,anchor:'end',color:'#ba6b3c'});});
 const loss=-Math.log(p[target]),nextLoss=-Math.log(q[target]);
 board.text('loss','损失（nat） '+loss.toFixed(3)+' → '+nextLoss.toFixed(3),12,340,{size:16});
 return {logits:o,target,eta,probabilities:p,gradient:g,updatedLogits:next,updatedProbabilities:q,loss,nextLoss,convention:'直接更新示例 logits 一步；不是全连接权重训练；自然对数'};
}
